const followData = $('Extract Follow Data').item.json;
const queryResult = $input.item.json;
const results = queryResult.result?.[0]?.results || [];
const rows = Array.isArray(results) ? results : (results.rows || []);
const cols = results.columns || ['click_id','timestamp','tag','ad_code','line_oa_id','ip_address','user_agent','accept_language','ip_country','ip_asn','fbclid','fbc','fbp','pixel_id','capi_token','pixels','event_id'];
if (!rows || rows.length === 0) {
  return [{ json: { matched: false, reason: 'no_clicks_found', line_user_id: followData.line_user_id, line_id: followData.line_id } }];
}
const match = {};
if (Array.isArray(rows[0])) {
  cols.forEach((c, i) => match[c] = rows[0][i]);
} else {
